#!/usr/bin/env python3
"""Fixtures for cases_update.txt: an 8x6 destination family plus a zoo of
source rasters (aligned, misaligned, finer, rotated-free quirky origins,
nodata, multi-band, missing SRS/GT), destinations with internal tiled
overviews, a VRT destination and a cutline file."""
import os
import struct
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from mk_tail_fixtures import write_tif

OUT = sys.argv[1] if len(sys.argv) > 1 else '.'
os.makedirs(OUT, exist_ok=True)


def P(name):
    return os.path.join(OUT, name)


GK31 = [1, 1, 0, 3, 1024, 0, 1, 1, 1025, 0, 1, 1, 3072, 0, 1, 32631]


def write_tif_ovr(path, w, h, vals, gt, geokeys, levels):
    """Byte GTiff with internal tiled (128x128) overview IFDs, the way
    the reference lays down internal overviews."""
    px = bytes(vals)
    out = bytearray(struct.pack('<2sHI', b'II', 42, 0))

    def ifd(entries, next_off):
        b = struct.pack('<H', len(entries))
        for code, typ, cnt, val in entries:
            b += struct.pack('<HHII', code, typ, cnt, val)
        return b + struct.pack('<I', next_off)

    def pad(buf):
        if len(buf) & 1:
            buf += b'\0'
        return buf

    # main pixel data
    strip_off = 8
    out += px
    out = pad(out)

    # geo payloads
    scale_off = len(out)
    out += struct.pack('<3d', gt[1], -gt[5], 0.0)
    tie_off = len(out)
    out += struct.pack('<6d', 0.0, 0.0, 0.0, gt[0], gt[3], 0.0)
    gk_off = len(out)
    out += b''.join(struct.pack('<H', v) for v in geokeys)
    out = pad(out)

    # overview payloads: metadata string + tile data per level
    md = (b'<GDALMetadata><Item name="RESAMPLING" sample="0">NEAREST'
          b'</Item></GDALMetadata>\0')
    md_off = len(out)
    out += md
    out = pad(out)
    tile_offs = []
    for ow, oh, ovals in levels:
        tile = bytearray(128 * 128)
        for y in range(oh):
            for x in range(ow):
                tile[y * 128 + x] = ovals[y * ow + x]
        tile_offs.append(len(out))
        out += bytes(tile)

    # IFD chain: main first, then one per level
    main_cnt = 14 if geokeys else 13
    ifd_offs = []
    pos = len(out)
    for k in range(len(levels) + 1):
        ifd_offs.append(pos)
        pos += 2 + (main_cnt if k == 0 else 14) * 12 + 4
    main_entries = [
        (256, 3, 1, w), (257, 3, 1, h), (258, 3, 1, 8), (259, 3, 1, 1),
        (262, 3, 1, 1), (273, 4, 1, strip_off), (277, 3, 1, 1),
        (278, 3, 1, h), (279, 4, 1, len(px)), (284, 3, 1, 1),
        (339, 3, 1, 1), (33550, 12, 3, scale_off),
        (33922, 12, 6, tie_off),
    ]
    if geokeys:
        main_entries.append((34735, 3, len(geokeys), gk_off))
    out += ifd(main_entries, ifd_offs[1] if levels else 0)
    for k, (ow, oh, ovals) in enumerate(levels):
        entries = [
            (254, 4, 1, 1), (256, 3, 1, ow), (257, 3, 1, oh),
            (258, 3, 1, 8), (259, 3, 1, 1), (262, 3, 1, 1),
            (277, 3, 1, 1), (284, 3, 1, 1), (322, 3, 1, 128),
            (323, 3, 1, 128), (324, 4, 1, tile_offs[k]),
            (325, 4, 1, 128 * 128), (339, 3, 1, 1),
            (42112, 2, len(md), md_off),
        ]
        nxt = ifd_offs[k + 2] if k + 1 < len(levels) else 0
        out += ifd(entries, nxt)
    out[4:8] = struct.pack('<I', ifd_offs[0])
    with open(path, 'wb') as f:
        f.write(bytes(out))


def near(vals, w, h, ow, oh):
    o = []
    for y in range(oh):
        sy = min(int(0.5 + y * h / oh), h - 1)
        for x in range(ow):
            sx = min(int(0.5 + x * w / ow), w - 1)
            o.append(vals[sy * w + sx])
    return o


